// ============================================================================
// public/src/features/lesson/lesson-ai-quiz.js
// EPHEMERAL AI QUIZ — temporary, in-page-only practice quiz generated by the
// lesson AI Agent via the shared `create_quiz` tool.
// ============================================================================

import { escapeHtml } from "../home/escape-html.js";

const norm = (v) => String(v ?? "").trim().toLocaleLowerCase().replace(/\s+/g, " ");
let activeQuiz = null;

function normalizeQuestion(raw, index) {
  if (!raw || typeof raw !== "object") return null;
  const text = String(raw.q ?? "").trim();
  if (!text) return null;

  const hasChoices = Array.isArray(raw.options) && raw.options.length >= 2 && Array.isArray(raw.correct);
  if (hasChoices) {
    const options = raw.options.slice(0, 10).map((o) => String(o ?? ""));
    const correct = raw.correct
      .map(Number)
      .filter((i) => Number.isInteger(i) && i >= 0 && i < options.length);
    if (!correct.length) return null;
    return {
      id: `q${index}`,
      kind: "choice",
      question: text.slice(0, 2000),
      options,
      correct,
      multiSelect: Boolean(raw.multiSelect) || correct.length > 1,
      explanation: String(raw.explanation ?? "").slice(0, 2000),
    };
  }

  const answer = String(raw.answer ?? "").trim();
  if (!answer) return null;
  return {
    id: `q${index}`,
    kind: "text",
    question: text.slice(0, 2000),
    answer: answer.slice(0, 500),
    explanation: String(raw.explanation ?? "").slice(0, 2000),
  };
}

export function createLessonQuiz(input = {}) {
  if (activeQuiz && !activeQuiz.graded && Object.keys(activeQuiz.answers).length > 0) {
    throw new Error("هناك تدريب قيد الإجابة بالفعل في هذه الصفحة. أنهِ التحقق من إجاباته أو أغلقه أولاً قبل إنشاء تدريب جديد.");
  }
  const questions = (Array.isArray(input.questions) ? input.questions : [])
    .slice(0, 50)
    .map(normalizeQuestion)
    .filter(Boolean);
  if (!questions.length) throw new Error("لا توجد أسئلة صالحة لإنشاء تدريب.");
  activeQuiz = {
    title: String(input.title || "تدريب سريع من الدرس").slice(0, 160),
    questions,
    answers: {},
    graded: false,
    current: 0,
  };
  return activeQuiz;
}

function isAnswered(q, value) {
  if (q.kind === "choice") {
    if (q.multiSelect) return Array.isArray(value) && value.length > 0;
    return value !== undefined && value !== null && String(value) !== "";
  }
  return norm(value) !== "";
}

function isCorrect(q, value) {
  if (q.kind === "choice") {
    if (q.multiSelect) {
      const picked = Array.isArray(value) ? value.map(Number).sort() : [];
      const expected = [...q.correct].sort();
      return picked.length === expected.length && picked.every((v, i) => v === expected[i]);
    }
    return q.correct.length === 1 && Number(value) === q.correct[0];
  }
  return norm(value) !== "" && norm(value) === norm(q.answer);
}

function renderQuestionNav(quiz) {
  if (quiz.questions.length < 2) return "";
  return (
    `<nav class="lesson-ai-quiz__nav" aria-label="التنقل بين أسئلة التدريب">` +
    quiz.questions.map((q, i) => {
      const classes = ["lesson-ai-quiz__nav-dot"];
      if (i === quiz.current) classes.push("is-active");
      if (isAnswered(q, quiz.answers[q.id])) classes.push("is-answered");
      return `<button type="button" class="${classes.join(" ")}" data-quiz-goto="${i}" aria-current="${i === quiz.current ? "step" : "false"}" aria-label="الانتقال إلى السؤال ${i + 1}">${i + 1}</button>`;
    }).join("") +
    `</nav>`
  );
}

function renderChoiceControl(q, value, graded) {
  const inputType = q.multiSelect ? "checkbox" : "radio";
  const picked = q.multiSelect ? (Array.isArray(value) ? value.map(String) : []) : String(value ?? "");
  return (
    `<div class="lesson-ai-quiz__options" role="group" aria-label="خيارات الإجابة">` +
    q.options.map((opt, i) => {
      const checked = q.multiSelect ? picked.includes(String(i)) : picked === String(i);
      const isCorrectOpt = graded && q.correct.includes(i);
      const isWrongPick = graded && checked && !isCorrectOpt;
      const classes = ["lesson-ai-quiz__option"];
      if (checked && !graded) classes.push("is-selected");
      if (isCorrectOpt) classes.push("is-correct-option");
      if (isWrongPick) classes.push("is-wrong-option");
      return (
        `<label class="${classes.join(" ")}">` +
        `<span class="lesson-ai-quiz__option-index" aria-hidden="true">${i + 1}</span>` +
        `<span class="lesson-ai-quiz__option-text">${escapeHtml(opt)}</span>` +
        `<input type="${inputType}" name="${escapeHtml(q.id)}" value="${i}" ${checked ? "checked" : ""} ${graded ? "disabled" : ""}>` +
        `</label>`
      );
    }).join("") +
    `</div>`
  );
}

function renderTextControl(q, value, graded) {
  return (
    `<label class="lesson-ai-quiz__text-wrap">` +
    `<span class="lesson-ai-quiz__text-label">إجابتك</span>` +
    `<input class="lesson-ai-quiz__text" type="text" data-answer="${escapeHtml(q.id)}" value="${escapeHtml(value || "")}" ${graded ? "disabled" : ""} dir="auto" autocomplete="off" placeholder="اكتب إجابتك هنا">` +
    `</label>`
  );
}

function renderFeedback(q, value, graded) {
  if (!graded) return "";
  const correct = isCorrect(q, value);
  const referenceAnswer = q.kind === "choice" ? q.correct.map((i) => q.options[i]).join("، ") : q.answer;
  const label = q.kind === "text"
    ? (correct ? "مطابقة للإجابة المرجعية" : "غير مطابقة — قارن إجابتك بالمرجعية")
    : (correct ? "إجابة صحيحة" : "إجابة غير صحيحة");
  return (
    `<div class="lesson-ai-quiz__feedback ${correct ? "is-correct" : "is-incorrect"}" role="status">` +
    `<div class="lesson-ai-quiz__feedback-title">${escapeHtml(label)}</div>` +
    `<p>الإجابة المرجعية: <strong>${escapeHtml(referenceAnswer)}</strong></p>` +
    (q.explanation ? `<p>${escapeHtml(q.explanation)}</p>` : "") +
    (q.kind === "text" && !correct ? `<p class="lesson-ai-quiz__feedback-note">المقارنة هنا مطابقة نصية مُبسطة وليست حكمًا على صحة صياغة مختلفة.</p>` : "") +
    `</div>`
  );
}

export function renderLessonQuiz() {
  if (!activeQuiz) return "";
  const quiz = activeQuiz;
  const total = quiz.questions.length;
  const current = quiz.questions[Math.min(quiz.current, total - 1)];
  const value = quiz.answers[current.id];
  const answeredCount = quiz.questions.filter((q) => isAnswered(q, quiz.answers[q.id])).length;
  const score = quiz.questions.filter((q) => isCorrect(q, quiz.answers[q.id])).length;
  const percent = Math.round((answeredCount / total) * 100);
  const progressLabel = quiz.graded ? `النتيجة ${score} من ${total}` : `أُجيب عن ${answeredCount} من ${total}`;

  const prevDisabled = quiz.current === 0 ? "disabled" : "";
  const nextDisabled = quiz.current >= total - 1 ? "disabled" : "";
  const action = quiz.graded
    ? `<button type="button" class="lesson-ai-quiz__submit" data-quiz-reset>إعادة المحاولة</button>`
    : `<button type="button" class="lesson-ai-quiz__submit" data-quiz-grade ${answeredCount === 0 ? "disabled" : ""}>تحقق من الإجابات</button>`;

  return (
    `<section class="lesson-ai-quiz" aria-label="تدريب مؤقت من الدرس">` +
    `<header class="lesson-ai-quiz__header">` +
    `<div class="lesson-ai-quiz__heading">` +
    `<span class="lesson-ai-quiz__badge">تدريب مؤقت</span>` +
    `<h2>${escapeHtml(quiz.title)}</h2>` +
    `<p>لا يُحفظ هذا التدريب داخل «امتحاناتك».</p>` +
    `</div>` +
    `<button type="button" class="lesson-ai-quiz__close" data-quiz-close aria-label="إغلاق التدريب">×</button>` +
    `</header>` +
    `<div class="lesson-ai-quiz__meta">` +
    `<div class="lesson-ai-quiz__progress-line"><span>${escapeHtml(progressLabel)}</span><span>السؤال ${quiz.current + 1} من ${total}</span></div>` +
    `<div class="lesson-ai-quiz__progress-track" aria-hidden="true"><span style="width:${percent}%"></span></div>` +
    renderQuestionNav(quiz) +
    `</div>` +
    `<div class="lesson-ai-quiz__question">` +
    `<div class="lesson-ai-quiz__question-kicker">السؤال ${quiz.current + 1}</div>` +
    `<h3 id="lessonAiQuizQuestion">${escapeHtml(current.question)}</h3>` +
    (current.kind === "choice" ? renderChoiceControl(current, value, quiz.graded) : renderTextControl(current, value, quiz.graded)) +
    renderFeedback(current, value, quiz.graded) +
    `</div>` +
    `<footer class="lesson-ai-quiz__footer">` +
    action +
    `<div class="lesson-ai-quiz__steps" role="group" aria-label="التنقل في التدريب">` +
    `<button type="button" class="lesson-ai-quiz__step" data-quiz-prev ${prevDisabled}>السابق</button>` +
    `<button type="button" class="lesson-ai-quiz__step" data-quiz-next ${nextDisabled}>التالي</button>` +
    `</div>` +
    `</footer>` +
    `</section>`
  );
}

function syncQuizIndicators(section, quiz) {
  const total = quiz.questions.length;
  const answeredCount = quiz.questions.filter((q) => isAnswered(q, quiz.answers[q.id])).length;
  const progressLabel = section.querySelector(".lesson-ai-quiz__progress-line span:first-child");
  const currentLabel = section.querySelector(".lesson-ai-quiz__progress-line span:last-child");
  const fill = section.querySelector(".lesson-ai-quiz__progress-track > span");
  if (progressLabel) progressLabel.textContent = quiz.graded ? `النتيجة ${quiz.questions.filter((q) => isCorrect(q, quiz.answers[q.id])).length} من ${total}` : `أُجيب عن ${answeredCount} من ${total}`;
  if (currentLabel) currentLabel.textContent = `السؤال ${quiz.current + 1} من ${total}`;
  if (fill) fill.style.width = `${Math.round((answeredCount / total) * 100)}%`;
  section.querySelectorAll("[data-quiz-goto]").forEach((btn) => {
    const i = Number(btn.dataset.quizGoto);
    const q = quiz.questions[i];
    btn.classList.toggle("is-active", i === quiz.current);
    btn.classList.toggle("is-answered", isAnswered(q, quiz.answers[q.id]));
    btn.setAttribute("aria-current", i === quiz.current ? "step" : "false");
  });
  const grade = section.querySelector("[data-quiz-grade]");
  if (grade) grade.disabled = answeredCount === 0;
}

export function equipLessonQuiz(root, rerender) {
  const section = root.querySelector(".lesson-ai-quiz");
  if (!section || !activeQuiz) return;
  const quiz = activeQuiz;

  section.querySelector("[data-quiz-close]")?.addEventListener("click", () => {
    activeQuiz = null;
    rerender();
  });

  section.querySelectorAll('input[type="radio"][name^="q"]').forEach((el) => {
    el.addEventListener("change", () => {
      quiz.answers[el.name] = el.value;
      syncQuizIndicators(section, quiz);
      section.querySelectorAll(".lesson-ai-quiz__option").forEach((option) => option.classList.remove("is-selected"));
      el.closest(".lesson-ai-quiz__option")?.classList.add("is-selected");
    });
  });

  section.querySelectorAll('input[type="checkbox"][name^="q"]').forEach((el) => {
    el.addEventListener("change", () => {
      const checked = Array.from(section.querySelectorAll(`input[type="checkbox"][name="${CSS.escape(el.name)}"]:checked`)).map((c) => c.value);
      quiz.answers[el.name] = checked;
      section.querySelectorAll(`input[name="${CSS.escape(el.name)}"]`).forEach((input) => input.closest(".lesson-ai-quiz__option")?.classList.toggle("is-selected", input.checked));
      syncQuizIndicators(section, quiz);
    });
  });

  section.querySelectorAll("[data-answer]").forEach((el) => {
    el.addEventListener("input", () => {
      quiz.answers[el.dataset.answer] = el.value;
      syncQuizIndicators(section, quiz);
    });
  });

  section.querySelector("[data-quiz-prev]")?.addEventListener("click", () => {
    quiz.current = Math.max(0, quiz.current - 1);
    rerender();
  });
  section.querySelector("[data-quiz-next]")?.addEventListener("click", () => {
    quiz.current = Math.min(quiz.questions.length - 1, quiz.current + 1);
    rerender();
  });
  section.querySelectorAll("[data-quiz-goto]").forEach((btn) => {
    btn.addEventListener("click", () => {
      quiz.current = Math.max(0, Math.min(quiz.questions.length - 1, Number(btn.dataset.quizGoto) || 0));
      rerender();
    });
  });
  section.querySelector("[data-quiz-grade]")?.addEventListener("click", () => {
    quiz.graded = true;
    rerender();
    root.querySelector(".lesson-ai-quiz__feedback")?.scrollIntoView({ behavior: "smooth", block: "nearest" });
  });
  section.querySelector("[data-quiz-reset]")?.addEventListener("click", () => {
    quiz.answers = {};
    quiz.graded = false;
    quiz.current = 0;
    rerender();
  });
}

export function hasActiveLessonQuiz() {
  return activeQuiz !== null;
}
